  const y0 = Math.max(1, Math.floor(px_per_unit * (xy[1] - range)));
  const x1 = Math.min(canvas.width, Math.ceil(px_per_unit * (xy[0] + range)));
  const y1 = Math.min(canvas.height, Math.ceil(px_per_unit * (xy[1] + range)));
